/* ---------- Notifications ---------- */
.ntx{padding:var(--s-3);display:flex;flex-direction:column;gap:var(--s-2);min-height:360px}
/* on a card the inbox keeps the room its fullest list takes, so it stays centred while items arrive, after a filter and after Mark all read */
.stage-in>.ntx{min-height:inherit}
.ntx-h{display:flex;align-items:center;gap:var(--s-2);margin:0 -12px 2px;padding:2px var(--s-3) 10px var(--s-4);font-size:14px;border-bottom:1px solid var(--line)}
.ntx-h b{font-weight:500}
.ntx-ct{min-width:20px;height:20px;padding:0 6px;border-radius:var(--r-pill);background:var(--accent);color:var(--on-accent);font-size:11px;font-weight:500;display:grid;place-items:center;transition:transform .35s var(--ease),opacity .3s}
.ntx-ct.z{opacity:0;transform:scale(.5)}
.ntx-ct.bump{animation:ntb .45s var(--ease)}
@keyframes ntb{40%{transform:scale(1.3)}}
.ntx-sp{flex:1}
.ntx-tabs .seg2 button{font-size:12px;height:26px;padding:0 9px}
.ntx-list{display:flex;flex-direction:column}
.ntx-n{display:flex;gap:10px;padding:9px var(--s-2);border-radius:var(--r-in);text-align:left;width:100%;position:relative;transition:background .2s}
@media (hover:hover) and (pointer:fine){.ntx-n:hover{background:var(--row)}}
.ntx-n .ic{width:30px;height:30px;border-radius:10px;display:grid;place-items:center;flex:none}
.ntx-n .ic .av{width:30px;height:30px;font-size:11px}
.ntx-n .t{flex:1;min-width:0;font-size:13px;line-height:1.45;color:var(--fg2)}
.ntx-n .t b{font-weight:500;color:var(--fg)}
.ntx-n .t span{display:block;font-size:11.5px;color:var(--muted);margin-top:2px}
.ntx-n .u{width:7px;height:7px;border-radius:50%;background:var(--accent-mark,var(--accent));margin-top:6px;flex:none;transition:transform .3s var(--ease),opacity .3s}
.ntx-n.read .u{transform:scale(0);opacity:0}
.ntx-n.read .t{color:var(--muted)}
.ntx-n.new{animation:ntn .6s var(--ease) both}
@keyframes ntn{from{opacity:0;transform:translateY(-10px);filter:blur(4px)}}
.ntx-e{padding:40px 10px;text-align:center;font-size:13px;color:var(--muted)}

DM.def('notifications', (r, c) => {
  let N = [
    { k:'agent', ic:'ok', col:'var(--ok)', t:'<b>Pricing audit</b> finished. 2 fixes ready to review', w:'4 min ago' },
    { k:'men', av:['MK','var(--pl)'], t:'<b>Maya</b> mentioned you in Checkout flow', w:'20 min ago' },
    { k:'agent', ic:'alert', col:'var(--warn)', t:'<b>Token export</b> paused at the $5 cap', w:'1 hour ago' },
    { k:'men', av:['JO','var(--pm)'], t:'<b>Jon</b> asked for your review on PR #284', w:'2 hours ago', read:true }
  ];
  const list = $('.ntx-list', r), ct = $('.ntx-ct', r); let f = 'all';
  const count = (bump) => { const n = N.filter(x => !x.read).length; ct.textContent = n; ct.classList.toggle('z', !n); if (bump){ ct.classList.remove('bump'); void ct.offsetWidth; ct.classList.add('bump'); } };
  const row = x => `<button class="ntx-n${x.read ? ' read' : ''}"><span class="ic" ${x.ic ? `style="color:${x.fg || x.col};background:color-mix(in srgb,${x.col} 13%,transparent)"` : ''}>${x.ic ? I(x.ic,'xs') : AV(x.av[0], x.av[1])}</span><span class="t">${x.t}<span>${x.w}</span></span><span class="u"></span></button>`;
  function paint(anim){ const L = N.filter(x => f === 'all' || x.k === f); list.innerHTML = L.length ? L.map(row).join('') : '<div class="ntx-e">Nothing here yet</div>';
    $$('.ntx-n', list).forEach((b, i) => b.onclick = () => { L[i].read = !L[i].read; b.classList.toggle('read', L[i].read); count(); });
    if (anim) stagger($$('.ntx-n', list), 40); count(); }
  seg($('.ntx-tabs .seg2', r), v => { f = v; paint(true); });
  $('.ntx-all', r).onclick = () => { N.forEach(x => x.read = true); $$('.ntx-n', list).forEach((b, i) => c.later(i * 50, () => b.classList.add('read'))); count(); };
  paint(true);
  const incoming = [{ k:'agent', ic:'spark', col:'var(--accent-mark,var(--accent))', fg:'var(--accent-fg,var(--accent))', t:'<b>Weekly design QA</b> started on 12 frames', w:'Just now' }, { k:'men', av:['AR','var(--pp)'], t:'<b>Ari</b> replied: “Looks great, ship it”', w:'Just now' }];
  // two items arrive while you watch; once you click or type in the inbox the preview leaves it to you, so a tab you
  // picked or a Mark all read stays as you left it
  incoming.forEach((x, i) => c.later(2200 + i * 2600, () => { if (c.mine) return; N.unshift(x); if (f === 'all' || f === x.k){ const el = html(row(x)); el.classList.add('new'); list.prepend(el); $('.ntx-e', list)?.remove(); el.onclick = () => { x.read = !x.read; el.classList.toggle('read', x.read); count(); }; } count(true); }));
});
